/* Selected picture-book town: isometric layers, walkable ground, building occlusion, and business panels. Memory only. */
const Game={
  profiles:{},night:false,sound:false,zoom:1,pan:{x:0,y:0},frame:0,arrival:null,activePlace:null,
  syncOrientation(){const portrait=gameMode&&matchMedia('(orientation: portrait)').matches;document.body.classList.toggle('landscape-required',portrait);document.getElementById('landscape-notice').hidden=!portrait;for(const id of ['app','prototype-controls','modal'])document.getElementById(id).inert=portrait;if(portrait)this.cancelWalk();},
  places:{savings:{name:'储蓄小屋',subtitle:'让努力慢慢长',x:285,y:372,labelX:267,labelY:173,view:'market',icon:'leaf'},wish:{name:'愿望工坊',subtitle:'给未来一个小约定',x:508,y:304,labelX:535,labelY:93,view:'wish',icon:'star'},tasks:{name:'委托小铺',subtitle:'去生活里赚第一笔钱',x:589,y:390,labelX:612,labelY:263,view:'tasks',icon:'task'},growth:{name:'时光树',subtitle:'看见自己的成长',x:466,y:432,labelX:491,labelY:453,view:'growth',icon:'chart'},journal:{name:'小镇信箱',subtitle:'每一笔都有故事',x:361,y:420,labelX:361,labelY:433,view:'wallet',icon:'book'}},
  local(){return this.profiles[state.profileId]??= {x:400,y:380,visited:[],lastAssets:Engine.assets(state),lastYield:state.bonusEarned};},
  quest(){const t=state.tasks.find(t=>t.id==='books')||state.tasks[0];if(pendingTasks().length)return {title:'把努力交给家长看看',text:'已经在现实中完成了吗？请家长确认并兑现报酬。',cta:'请家长来看',parent:true,place:'tasks'};if(t.status==='available')return {title:'一份努力，一个小小愿望',text:'去委托小铺，接一件生活里能做到的小事。',cta:'去接一个委托',place:'tasks'};if(t.status==='accepted')return {title:'这份劳动，在生活里完成',text:'离开屏幕动动手，做完后回来告诉家长。',cta:'看看我的委托',place:'tasks'};if(!state.bonusEarned)return {title:'给努力一点时间',text:'去储蓄小屋，为自己赚来的钱作一次安排。',cta:'去储蓄小屋',place:'savings'};return {title:'收益的下一站，由我决定',text:'拿出来满足愿望，还是留下来参与下一次积累？',cta:'看看我的持有',place:'savings',screen:'holdings'};},
  render(){
    this.stop();document.body.classList.add('game-mode');const local=this.local(),quest=this.quest(),net=Math.max(0,Engine.net(state)),pct=percent(net/state.goal*100);
    document.getElementById('app').innerHTML=`<main class="game-shell ${this.night?'is-evening':''}" aria-label="钱钱小镇互动场景"><div class="game-sky"><span class="sky-cloud cloud-one"></span><span class="sky-cloud cloud-two"></span><span class="sky-bird">⌁</span><span class="sky-star star-one">✦</span><span class="sky-star star-two">✧</span></div><header class="game-hud"><button class="game-profile" data-action="profiles" aria-label="切换孩子档案"><span class="game-portrait">${Art.mascot(50)}</span><span><small>今天也是自己的主角</small><strong>${e(state.child)}的小镇 ${icon('chevron',13)}</strong></span></button><button class="game-coins" data-action="game-view" data-view="wallet" aria-label="打开我的零钱口袋"><span class="game-coin-icon">${icon('coin',23)}</span><span><small>可以自己安排的零钱</small><strong>¥${money(state.wallet)}</strong></span><i>＋</i></button><div class="game-top-buttons"><button class="game-round" data-action="game-help" aria-label="小镇怎么玩">?</button><button class="game-round parent-entry" data-action="go" data-view="parent" aria-label="进入家长空间">${icon('parent',20)}</button></div></header><aside class="game-quest"><span class="quest-book">${icon('book',24)}</span><div class="grow"><small>今天的故事</small><h1>${quest.title}</h1><p>${quest.text}</p></div><button class="quest-go" data-action="game-quest" aria-label="${quest.cta}">${icon('arrow',20)}<span>${quest.cta}</span></button></aside><div class="game-title"><span>欢迎回到</span><h2>钱钱小镇</h2><p>把小小努力，存成大大愿望。</p></div><section id="game-stage" class="game-stage" aria-label="点击草地行走，点击建筑走近互动"><div id="game-world" class="game-world">${GameArt.world()}<div class="map-pins">${Object.entries(this.places).filter(([id])=>id!=='journal').map(([id,p])=>`<button id="pin-${id}" class="map-pin pin-${id} ${id===quest.place?'has-story':''}" style="left:${p.labelX}px;top:${p.labelY}px" data-action="game-place" data-place="${id}" aria-label="走到${p.name}"><span>${icon(p.icon,14)}<b>${p.name}</b>${id===quest.place?'<i>!</i>':''}</span><small>${p.subtitle}</small></button>`).join('')}</div></div><div id="game-speech" class="game-speech" role="status" aria-live="polite">点点草地，我会走过去。<br>也可以点一座小屋，进去看看。</div><div id="scene-particles" class="scene-particles" aria-hidden="true"></div></section><aside class="game-wish" aria-label="我的愿望进度"><div class="wish-mini-art">${Art.telescope()}</div><div class="grow"><small>我正在慢慢实现</small><strong>${e(state.goalName||'第一架天文望远镜')}</strong><div class="game-wish-track"><span style="width:${pct}%"></span></div><span class="tiny muted">${money(net)} / ${money(state.goal)} 元${Engine.debt(state)?' · 已扣计划待还':''}</span></div><button class="game-round" data-action="game-place" data-place="wish" aria-label="去愿望工坊">${icon('arrow',16)}</button></aside><div class="game-camera"><button data-action="game-zoom" data-step="1" aria-label="放大小镇">＋</button><button data-action="game-zoom" data-step="-1" aria-label="缩小小镇">−</button><button data-action="game-camera-reset" aria-label="镜头回到小镇">${icon('home',16)}</button></div><div class="game-atmosphere"><button data-action="game-evening" aria-label="切换白天与黄昏">${icon('sun',17)}<span>${this.night?'黄昏':'午后'}</span></button><button data-action="game-sound" aria-pressed="${this.sound}" aria-label="切换互动音效">♫<span>声音${this.sound?'开':'关'}</span></button></div><div class="game-discoveries"><span>${icon('leaf',13)} 小镇足迹 ${local.visited.length}/4</span><span>${state.now}</span></div><nav class="game-dock" aria-label="小镇工具"><button data-action="game-map" class="selected">${icon('home',24)}<span>小镇地图</span></button><button data-action="game-view" data-view="wallet">${icon('wallet',24)}<span>我的口袋</span></button><button data-action="game-place" data-place="tasks">${icon('task',24)}<span>生活委托</span></button><button data-action="game-place" data-place="wish">${icon('star',24)}<span>愿望清单</span></button><button data-action="game-place" data-place="growth">${icon('book',24)}<span>成长手账</span></button></nav><p class="game-prototype-note">2.5D 场景原型 · 刷新重置</p></main>`;
    renderControls();this.layout();this.updatePlayer();this.bindStage();this.observer=new ResizeObserver(()=>this.layout());this.observer.observe(document.getElementById('game-stage'));
    document.querySelector('#world-growth .growth-stars').style.opacity=state.bonusEarned>0?'1':'.25';
    document.querySelector('.player-scarf').style.display=state.profileId==='xiaohe'?'':'none';
    const gain=Engine.assets(state)-local.lastAssets;if(gain>0&&local.lastYield!==state.bonusEarned)this.reward(`+${money(state.bonusEarned-local.lastYield)} 元 · 按约结算`);else if(gain>0)this.reward(`+${money(gain)} 元 · 劳动报酬`);local.lastAssets=Engine.assets(state);local.lastYield=state.bonusEarned;
  },
  cancelWalk(){cancelAnimationFrame(this.frame);this.frame=0;this.arrival=null;this.updatePlayer(false);document.getElementById('walk-path')?.setAttribute('d','');document.getElementById('walk-target')?.setAttribute('opacity','0');},
  stop(){cancelAnimationFrame(this.frame);this.frame=0;this.arrival=null;this.observer?.disconnect();},
  layout(){const stage=document.getElementById('game-stage'),world=document.getElementById('game-world');if(!stage||!world)return;const rect=stage.getBoundingClientRect();const compact=matchMedia('(max-height:650px) and (orientation:landscape)').matches;this.scale=Math.min(rect.width/760,rect.height/(compact?460:500),1.6)*this.zoom;world.style.transform=`translate(-50%,-50%) translate(${this.pan.x}px,${this.pan.y}px) scale(${this.scale})`;world.style.setProperty('--pin-scale',Math.min(1.45,1/this.scale));},
  updatePlayer(walking=false){const p=this.local(),player=document.getElementById('game-player');if(!player)return;player.setAttribute('transform',`translate(${p.x.toFixed(2)} ${p.y.toFixed(2)})`);player.setAttribute('data-depth',p.y);player.classList.toggle('is-walking',walking);document.querySelector('.game-shell')?.classList.toggle('is-travelling',walking);const actors=document.getElementById('world-actors');for(const node of Array.from(actors.children).sort((a,b)=>Number(a.dataset.depth)-Number(b.dataset.depth)))actors.append(node);},
  inside(p,poly){let result=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p.y)!==(b[1]>p.y)&&p.x<(b[0]-a[0])*(p.y-a[1])/(b[1]-a[1])+a[0])result=!result;}return result;},
  canWalk(p){if(!this.inside(p,[[99,301],[412,177],[751,322],[459,470]]))return false;const blocked=[[[185,328],[264,371],[335,333],[255,289]],[[450,243],[534,290],[619,246],[533,198]],[[566,355],[628,392],[684,363],[619,326]]];return !blocked.some(poly=>this.inside(p,poly))&&![[145,333],[393,241],[710,334]].some(([x,y])=>Math.hypot(x-p.x,y-p.y)<11);},
  nearest(p){for(let r=0;r<=7;r++){const candidates=[];for(let x=-r;x<=r;x++)for(let y=-r;y<=r;y++){const n={x:Math.round(p.x/10)*10+x*10,y:Math.round(p.y/10)*10+y*10};if(this.canWalk(n))candidates.push(n);}if(candidates.length)return candidates.sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];}return null;},
  route(target){const start=this.nearest(this.local()),end=this.nearest(target);if(!start||!end)return [];const key=p=>`${p.x},${p.y}`,open=[{...start,g:0,f:0}],best=new Map([[key(start),0]]),previous=new Map(),closed=new Set();let found=null;while(open.length){open.sort((a,b)=>a.f-b.f);const current=open.shift(),id=key(current);if(closed.has(id))continue;closed.add(id);if(id===key(end)){found=current;break;}for(const [dx,dy] of [[10,0],[-10,0],[0,10],[0,-10],[10,10],[-10,10],[10,-10],[-10,-10]]){const next={x:current.x+dx,y:current.y+dy};if(!this.canWalk(next)||dx&&dy&&(!this.canWalk({x:current.x+dx,y:current.y})||!this.canWalk({x:current.x,y:current.y+dy})))continue;const cost=current.g+Math.hypot(dx,dy),nextId=key(next);if(cost>=(best.get(nextId)??Infinity))continue;best.set(nextId,cost);previous.set(nextId,id);open.push({...next,g:cost,f:cost+Math.hypot(next.x-end.x,next.y-end.y)});}}
    if(!found)return [];const path=[end];let id=key(end);while(previous.has(id)){id=previous.get(id);const [x,y]=id.split(',').map(Number);path.unshift({x,y});}if(this.canWalk(target))path.push(target);return path;
  },
  walk(target,onArrival=null){if(!document.getElementById('game-player'))return;const path=this.route(target);if(!path.length)return this.say('这边走不过去，我们沿着小路走吧。');cancelAnimationFrame(this.frame);this.arrival=onArrival;const profile=state.profileId,p=this.local(),guide=document.getElementById('walk-path'),marker=document.getElementById('walk-target');guide.setAttribute('d',`M${p.x} ${p.y}`+path.map(n=>`L${n.x} ${n.y}`).join(''));marker.setAttribute('transform',`translate(${target.x} ${target.y})`);marker.setAttribute('opacity','1');let index=0,last=performance.now();const step=now=>{if(state.profileId!==profile||!document.getElementById('game-player'))return;const dt=Math.min((now-last)/1000,.05);last=now;let travel=150*dt;while(index<path.length&&travel>=0){const next=path[index],distance=Math.hypot(next.x-p.x,next.y-p.y);if(distance<=travel||distance<.2){p.x=next.x;p.y=next.y;travel-=distance;index++;}else{p.x+=(next.x-p.x)/distance*travel;p.y+=(next.y-p.y)/distance*travel;travel=-1;}}this.updatePlayer(index<path.length);if(index<path.length)this.frame=requestAnimationFrame(step);else{this.frame=0;guide.setAttribute('d','');marker.setAttribute('opacity','0');const done=this.arrival;this.arrival=null;done?.();}};this.frame=requestAnimationFrame(step);},
  visit(id,screen=null){const place=this.places[id];if(!place)return;this.activePlace=id;document.querySelectorAll('.world-house').forEach(n=>n.classList.toggle('is-destination',n.dataset.place===id));this.say(`去${place.name}啦，跟我走。`);this.chime();this.walk(place,()=>{const local=this.local();if(id!=='journal'&&!local.visited.includes(id)){local.visited.push(id);const label=document.querySelector('.game-discoveries span');if(label)label.innerHTML=`${icon('leaf',13)} 小镇足迹 ${local.visited.length}/4`;}this.say({tasks:'欢迎！先说好要求，再去生活里完成。',savings:'你赚来的钱，值得认真安排。',wish:'愿望可以慢慢攒，也可以先和家长约定。',growth:'每一份变化，都有自己的来处。',journal:'你的每一个选择，小镇都记得。'}[id]);this.openView(screen||place.view);});},
  say(text){const el=document.getElementById('game-speech');if(el){el.textContent=text;el.classList.add('speaking');clearTimeout(this.speechTimer);this.speechTimer=setTimeout(()=>el.classList.remove('speaking'),6000);}},
  reward(text){const stage=document.getElementById('scene-particles');if(!stage)return;const item=document.createElement('span');item.className='scene-reward';item.textContent=text;stage.append(item);setTimeout(()=>item.remove(),3000);this.chime();},
  chime(){if(!this.sound)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;this.audio??=new Audio();this.audio.resume();for(const [i,f] of [523,659,784].entries()){const oscillator=this.audio.createOscillator(),gain=this.audio.createGain(),time=this.audio.currentTime+i*.075;oscillator.type='sine';oscillator.frequency.value=f;gain.gain.setValueAtTime(.035,time);gain.gain.exponentialRampToValueAtTime(.001,time+.19);oscillator.connect(gain);gain.connect(this.audio.destination);oscillator.start(time);oscillator.stop(time+.2);}},
  bindStage(){const stage=document.getElementById('game-stage');let gesture=null;stage.addEventListener('pointerdown',event=>{if(event.target.closest('button'))return;gesture={x:event.clientX,y:event.clientY,pan:{...this.pan},moved:false,place:event.target.closest('[data-place]')?.dataset.place};stage.setPointerCapture(event.pointerId);});stage.addEventListener('pointermove',event=>{if(!gesture)return;const dx=event.clientX-gesture.x,dy=event.clientY-gesture.y;if(Math.hypot(dx,dy)>7)gesture.moved=true;if(gesture.moved){this.pan.x=Math.max(-350,Math.min(350,gesture.pan.x+dx));this.pan.y=Math.max(-220,Math.min(220,gesture.pan.y+dy));this.layout();}});stage.addEventListener('pointerup',event=>{if(!gesture)return;const current=gesture;gesture=null;if(current.moved)return;if(current.place)return this.visit(current.place);const world=document.getElementById('game-world').getBoundingClientRect(),p={x:(event.clientX-world.left)/this.scale,y:(event.clientY-world.top)/this.scale};if(this.canWalk(p)){this.say('好呀，我们去这里。');this.walk(p);}else this.say('点点小路或草地，我就能走过去。');});stage.addEventListener('pointercancel',()=>{gesture=null;});},
  roomIntro(kind,title,speech){return `<div class="scene-room-intro">${GameArt.room(kind)}<div class="npc-dialogue"><span class="npc-face">${Art.mascot(50)}</span><div><small>${title}</small><p>${speech}</p></div></div></div>`;},
  content(screen){
    if(screen==='tasks')return this.roomIntro('tasks','小铺掌柜','报酬来自现实里的劳动。挑一件能做的事，我们先和家长说好。')+`<div class="scene-task-board">${state.tasks.map(t=>`<button class="scene-commission" data-action="task-detail" data-id="${t.id}"><span class="commission-art">${taskArt(t)}</span><span class="grow"><strong>${e(t.name)}</strong><small>${statusLabel[t.status]} · ${e(t.duration)}</small></span><b>¥${money(t.amount)}</b>${icon('chevron',17)}</button>`).join('')}</div><p class="scene-rule-note">接下委托不会增加零钱；现实完成、家长确认并兑现后才入账。</p>`;
    if(screen==='market')return this.roomIntro('savings','储蓄小屋的阿栗','留下多少、等多久，都由你作选择。收益结算后，也可以选择它的下一站。')+`<div class="scene-money-strip"><span>口袋里 ¥${money(state.wallet)}</span><button data-action="game-view" data-view="holdings">持有中 ¥${money(Engine.holding(state))} ${icon('arrow',14)}</button></div><div class="scene-shelves">${['sprout','annual','dividend'].map(key=>{const p=Products[key];return `<button class="scene-product" data-action="product" data-product="${key}"><span>${Art.tree(key)}</span><strong>${p.name}</strong><small>${p.days} 天${key==='dividend'?'一期':'到期'} · ${p.minimum/100} 元起</small><b>${fixedRate()}<em>家庭约定年化</em></b><i>${key==='dividend'?'我来选分红方式':'了解这份计划'} ${icon('arrow',13)}</i></button>`;}).join('')}</div><div class="scene-classroom"><span>${icon('book',20)} 产品小课堂</span>${button('基金分红','dividend-lesson','data-mode="cash"','ghost small')}${button('净值涨跌','product','data-product="index"','ghost small')}</div><p class="scene-rule-note">家庭教学利率，不是市场报价。每笔收益由家长事先约定并承担。</p>`;
    if(screen==='holdings')return this.roomIntro('savings','我的积累架','预计收益还不是口袋里的钱。到期结算后，取出还是留下，由你决定。')+`<div class="scene-holdings">${Engine.active(state).map(p=>`<article class="scene-holding"><span>${Art.tree(p.product)}</span><div class="grow"><h3>${Products[p.product].name}</h3><p>本金 ¥${money(p.principal)} · ${p.end} 到期</p><small>本期预计收益 ¥${money(p.expected)}</small>${p.product==='dividend'?`<div class="mt8">${link(p.distribution==='cash'?'现金分红 · 修改方式':'红利再投 · 修改方式','distribution',`data-id="${p.id}"`)}</div>`:''}</div>${button('查看','holding-detail',`data-id="${p.id}"`,'secondary small')}</article>`).join('')||'<p class="empty">这里还没有持有计划，先了解一份适合自己的吧。</p>'}</div><div class="mt16">${button('再安排一笔零钱','game-view','data-view="market"','secondary full')}</div>`;
    if(screen==='wish'){const net=Math.max(0,Engine.net(state)),gap=Math.max(0,state.goal-net);return this.roomIntro('wish','愿望工坊的星星','今天花掉也好，留给未来也好。先想想自己为什么想要它。')+`<section class="scene-wish-detail"><div>${Art.telescope()}</div><h3>${e(state.goalName||'第一架天文望远镜')}</h3><p>扣除计划待还后，已经积累 <b>¥${money(net)}</b> / ¥${money(state.goal)}</p><div class="game-wish-track"><span style="width:${percent(net/state.goal*100)}%"></span></div><small>${gap?`还差 ${money(gap)} 元，每一份努力都让它更近。`:'目标金额已达到，取用前记得看可用零钱和持有期限。'}</small></section><div class="scene-wish-actions">${button('换一个愿望','edit-goal','','ghost')}${button('申请领取零钱','withdraw',`data-purpose="为${e(state.goalName||'我的愿望')}做准备"`,'secondary')}${button('制定预支与还款计划','game-view','data-view="loans"','primary')}</div><p class="scene-rule-note">预支可以由家长约定利息。先看清每月还款，再决定是否提前实现愿望。</p>`;}
    if(screen==='wallet')return this.roomIntro('tasks','我的零钱口袋','劳动、收益、存入和还款，都有自己的记录。')+`<div class="scene-pocket"><small>现在可以安排</small><strong>¥${money(state.wallet)}</strong><p>持有本金 ¥${money(Engine.holding(state))} · 待领取 ¥${money(Engine.pendingCash(state))}</p>${button('申请实际领取','withdraw','','primary')}${link('查看预支与还款','game-view','data-view="loans"')}</div>${Engine.debt(state)?`<p class="scene-rule-note">计划待还 ¥${money(Engine.debt(state))}，包含未来利息；不会自动扣走你的劳动报酬或现金分红。</p>`:''}${ledgerMarkup(state.history)}`;
    if(screen==='loans')return this.roomIntro('wish','先把未来的安排说清楚','家长可以提前垫付购买；借来的钱要按约偿还，不会变成你的劳动收入。')+`<div class="scene-loans">${state.loans.map(l=>loanCard(l)).join('')||'<p class="scene-rule-note">还没有预支计划。可以先写提议，看清利率和每月还款，再作决定。</p>'}</div><div class="mt16">${button('写一份预支提议','new-loan','','primary full')}</div>${debtCard()}`;
    return this.roomIntro('growth','时光树下的成长手账','新的劳动增加本金，收益留下也会参与下一次积累。我们把它们分开记。')+growthPage()+`<p class="scene-rule-note">小镇足迹只是探索记录，不发放零钱；树上的光点来自已经结算的收益。</p>`;
  },
  openView(screen){if(!['tasks','market','holdings','wish','growth','wallet','loans'].includes(screen))screen='wallet';this.panel=screen;const titles={tasks:'委托小铺',market:'储蓄小屋',holdings:'储蓄小屋 · 我的持有',wish:'愿望工坊',growth:'时光树 · 成长手账',wallet:'我的零钱口袋',loans:'愿望工坊 · 预支与还款'};openModal(titles[screen],this.content(screen));document.getElementById('modal').classList.add('scene-panel');},
  help(){openModal('小镇怎么玩？',`<div class="modal-illustration">${Art.mascot(100)}</div><div class="timeline"><div class="timeline-item"><h4>点草地，让小松鼠走过去</h4><p>点建筑会沿可走的草地绕开房屋，到门口再进入。拖动空白处移动镜头，右侧 ＋ / − 缩放。</p></div><div class="timeline-item"><h4>小屋里，作自己的选择</h4><p>委托小铺接现实劳动，储蓄小屋安排本金与分红，愿望工坊查看目标、预支与月供。</p></div><div class="timeline-item"><h4>时间和成长，看得见</h4><p>劳动经家长确认兑现，收益按约到期才记账。右下角演示工具可以推进示例日期。</p></div></div><p class="tiny muted">电脑可用方向键移动，走近建筑后按 Enter 进入。家长口令 2580，小满 1111，小禾 2222。场景探索不会凭空增加钱。</p>${button('回小镇，出发吧','close-modal','','primary full')}`);}
};
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(!action.startsWith('game-'))return;event.preventDefault();if(action==='game-place')return Game.visit(target.dataset.place);if(action==='game-view')return Game.openView(target.dataset.view);if(action==='game-help')return Game.help();if(action==='game-quest'){const q=Game.quest();return q.parent?go('parent-tasks'):Game.visit(q.place,q.screen);}if(action==='game-zoom'){Game.zoom=Math.max(.7,Math.min(1.6,Game.zoom+Number(target.dataset.step)*.15));return Game.layout();}if(action==='game-map'||action==='game-camera-reset'){closeModal();Game.zoom=1;Game.pan={x:0,y:0};Game.layout();return Game.say('小镇在这里，今天想去哪里？');}if(action==='game-evening'){Game.night=!Game.night;return render();}if(action==='game-sound'){Game.sound=!Game.sound;const button=target;button.setAttribute('aria-pressed',Game.sound);button.querySelector('span').textContent=`声音${Game.sound?'开':'关'}`;Game.chime();return;}if(action==='game-mode'){closeModal();gameMode=!gameMode;const url=new URL(location.href);url.searchParams.set('mode',gameMode?'game':'app');history.replaceState(null,'',url);return go('home');}});
document.addEventListener('keydown',event=>{if(document.body.classList.contains('landscape-required')||!gameMode||view.startsWith('parent')||document.getElementById('modal').open||['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||event.target.closest('[contenteditable]'))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const p=Game.local(),dx=event.key==='ArrowLeft'?-30:event.key==='ArrowRight'?30:0,dy=event.key==='ArrowUp'?-20:event.key==='ArrowDown'?20:0;const target={x:p.x+dx,y:p.y+dy};if(Game.canWalk(target))Game.walk(target);}if(event.key==='Enter'&&!event.target.closest('button')){const near=Object.entries(Game.places).sort((a,b)=>Math.hypot(Game.local().x-a[1].x,Game.local().y-a[1].y)-Math.hypot(Game.local().x-b[1].x,Game.local().y-b[1].y))[0];if(Math.hypot(Game.local().x-near[1].x,Game.local().y-near[1].y)<85){event.preventDefault();Game.visit(near[0]);}}});

matchMedia('(orientation: portrait)').addEventListener('change',()=>{Game.syncOrientation();Game.layout();});
